package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/** Runs the real adapter over real HTTP against a local stand-in for the provider. */
class HttpPaymentGatewayTest {

    private record Received(String method, String path, String contentType, String body) {}

    private HttpServer provider;
    private final List<Received> received = new ArrayList<>();
    private int status;
    private String responseBody;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() throws Exception {
        provider = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        provider.createContext("/", exchange -> {
            var body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            received.add(new Received(
                    exchange.getRequestMethod(),
                    exchange.getRequestURI().getPath(),
                    exchange.getRequestHeaders().getFirst("Content-Type"),
                    body));
            var bytes = responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
            if (bytes.length > 0) exchange.getResponseBody().write(bytes);
            exchange.close();
        });
        provider.start();
        gateway = new HttpPaymentGateway(
                RestClient.builder().baseUrl("http://127.0.0.1:" + provider.getAddress().getPort()).build());
    }

    @AfterEach
    void stopProvider() {
        provider.stop(0);
    }

    @Test
    void the_authorization_is_posted_as_json_with_reference_amount_and_currency() throws Exception {
        respond(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        assertThat(received).hasSize(1);
        var request = received.get(0);
        assertThat(request.method()).isEqualTo("POST");
        assertThat(request.path()).isEqualTo("/v1/authorizations");
        assertThat(request.contentType()).startsWith("application/json");
        JsonNode json = new ObjectMapper().readTree(request.body());
        assertThat(json.size()).isEqualTo(3);
        assertThat(json.get("reference").asText()).isEqualTo("ORD-7");
        assertThat(json.get("amount").decimalValue()).isEqualByComparingTo("12.50");
        assertThat(json.get("amount").isNumber()).isTrue();
        assertThat(json.get("currency").asText()).isEqualTo("EUR");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        respond(200, "{\"status\":\"approved\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        respond(200, "{\"status\":\"declined\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_ignored() {
        respond(200, "{\"status\":\"approved\",\"id\":\"auth-1\",\"risk\":{\"score\":3}}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_a_decline_even_with_an_error_body() {
        respond(402, "{\"error\":\"card_refused\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
        assertThat(received).hasSize(1);
    }

    @Test
    void a_refusal_with_402_and_no_body_is_a_decline() {
        respond(402, "");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        respond(200, "{\"status\":\"pending\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_approved() {
        respond(200, "{\"decision\":\"approved\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_empty_answer_is_never_treated_as_approved() {
        respond(200, "");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_reported_as_a_failure_not_a_decline() {
        respond(400, "{\"error\":\"invalid_currency\"}");

        assertThatThrownBy(this::authorize)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        respond(503, "");

        assertThatThrownBy(this::authorize)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));
    }

    private void respond(int status, String body) {
        this.status = status;
        this.responseBody = body;
    }
}
